const bi=(pt,en)=>[pt,en];
const L=(title,text,formula,example,question,options,answer,why,type='choice')=>({title,text,formula,example,question,options,answer,why,type});
window.UNITS=[
{name:bi('Primeiras descobertas','First discoveries'),topic:bi('Fundamentos','Foundations'),icon:'📏',intro:bi('Medir, comparar e descobrir.','Measure, compare and discover.'),lessons:[
L(bi('O que podemos medir?','What can we measure?'),bi('Grandeza física é uma propriedade mensurável, como comprimento, massa ou tempo. Toda medida precisa de número e unidade. No Sistema Internacional (SI), usamos metro (m), quilograma (kg), segundo (s) e kelvin (K).','A physical quantity is a measurable property, such as length, mass or time. Every measurement needs a number and a unit. In the International System (SI), we use meters (m), kilograms (kg), seconds (s) and kelvin (K).'),'2 m',bi('Uma mesa mede 2 m. O número sozinho não diz se são metros ou centímetros.','A table is 2 m long. The number alone does not tell us whether we mean meters or centimeters.'),bi('Qual é a unidade SI de massa?','What is the SI unit of mass?'),[bi('Quilograma (kg)','Kilogram (kg)'),bi('Metro (m)','Meter (m)'),bi('Segundo (s)','Second (s)')],0,bi('Quilograma mede massa; metro mede comprimento; segundo mede tempo.','Kilograms measure mass; meters measure length; seconds measure time.')),
L(bi('Transformando unidades','Converting units'),bi('Converter unidades não muda o tamanho real, apenas sua representação. Um quilômetro tem 1.000 metros e uma hora tem 3.600 segundos. Para passar de km/h para m/s, divida por 3,6.','Converting units does not change actual size, only its representation. A kilometer has 1,000 meters and an hour has 3,600 seconds. To convert km/h to m/s, divide by 3.6.'),'1 km = 1.000 m · 1 h = 3.600 s',bi('18 km/h = 5 m/s: a bicicleta percorre 5 metros por segundo.','18 km/h = 5 m/s: the bicycle travels 5 meters each second.'),bi('Quanto vale 72 km/h em m/s? Digite o número.','How much is 72 km/h in m/s? Enter the number.'),[],20,bi('72 ÷ 3,6 = 20 m/s.','72 ÷ 3.6 = 20 m/s.'),'number'),
L(bi('Números e gráficos','Numbers and graphs'),bi('Notação científica escreve números como a × 10ⁿ, com 1 ≤ |a| < 10. Em gráficos, leia os nomes, unidades e escalas dos eixos. A inclinação indica quanto a grandeza vertical muda em relação à horizontal.','Scientific notation writes numbers as a × 10ⁿ, with 1 ≤ |a| < 10. On graphs, read axis names, units and scales. Slope tells how much the vertical quantity changes relative to the horizontal one.'),'3.000 = 3 × 10³',bi('Uma reta horizontal em posição × tempo representa posição constante.','A horizontal position–time line represents constant position.'),bi('Como escrevemos 50.000 em notação científica?','How do we write 50,000 in scientific notation?'),[bi('5 × 10⁴','5 × 10⁴'),bi('50 × 10⁴','50 × 10⁴'),bi('5 × 10⁻⁴','5 × 10⁻⁴')],0,bi('10⁴ = 10.000; então 5 × 10.000 = 50.000.','10⁴ = 10,000; so 5 × 10,000 = 50,000.')),
L(bi('Escalares e vetores','Scalars and vectors'),bi('Escalares, como massa e temperatura, não precisam de direção. Vetores, como força e deslocamento, têm módulo, direção e sentido. Uma seta representa um vetor: comprimento indica módulo e a ponta indica sentido.','Scalars, such as mass and temperature, do not need a direction. Vectors, such as force and displacement, have magnitude and direction. An arrow represents a vector: length indicates magnitude and its tip indicates direction.'),'→ 5 N',bi('“3 m para leste” descreve deslocamento; “3 kg” descreve massa.','“3 m east” describes displacement; “3 kg” describes mass.'),bi('Qual grandeza é vetorial?','Which quantity is a vector?'),[bi('Temperatura','Temperature'),bi('Massa','Mass'),bi('Força','Force')],2,bi('Empurrar para a esquerda é diferente de empurrar para a direita: força tem direção e sentido.','Pushing left differs from pushing right: force has a direction.'))]},
{name:bi('Tudo em movimento','Everything in motion'),topic:bi('Cinemática','Kinematics'),icon:'🛹',intro:bi('Da bicicleta ao foguete: siga cada movimento.','From bicycles to rockets: follow every motion.'),lessons:[
L(bi('Onde você está?','Where are you?'),bi('Posição depende de um referencial. Distância é todo o caminho percorrido; deslocamento é posição final menos inicial. Velocidade média usa deslocamento; rapidez média usa distância total.','Position depends on a reference frame. Distance is the whole path traveled; displacement is final minus initial position. Average velocity uses displacement; average speed uses total distance.'),'vₘ = Δx/Δt',bi('Andar 3 m e voltar 3 m dá distância de 6 m, mas deslocamento zero.','Walking 3 m and returning 3 m gives a distance of 6 m, but zero displacement.'),bi('De x = 2 m até x = 12 m em 5 s: qual a velocidade média?','From x = 2 m to x = 12 m in 5 s: what is average velocity?'),[bi('2 m/s','2 m/s'),bi('10 m/s','10 m/s'),bi('2,4 m/s','2.4 m/s')],0,bi('(12 − 2)/5 = 2 m/s.','(12 − 2)/5 = 2 m/s.')),
L(bi('Velocidade e aceleração','Velocity and acceleration'),bi('No movimento uniforme, velocidade é constante. Aceleração é mudança de velocidade por segundo. No movimento uniformemente variado, aceleração é constante. Aceleração negativa não significa sempre frear: depende do sentido da velocidade.','In uniform motion, velocity is constant. Acceleration is change in velocity per second. In uniformly accelerated motion, acceleration is constant. Negative acceleration does not always mean slowing down: it depends on velocity direction.'),'x = x₀ + v₀t + ½at² · v = v₀ + at',bi('Do repouso com a = 2 m/s², após 3 s: v = 6 m/s e Δx = 9 m.','From rest at a = 2 m/s², after 3 s: v = 6 m/s and Δx = 9 m.'),bi('Do repouso, a = 3 m/s² durante 4 s. Qual v em m/s?','From rest, a = 3 m/s² for 4 s. What is v in m/s?'),[],12,bi('v = 0 + 3 × 4 = 12 m/s.','v = 0 + 3 × 4 = 12 m/s.'),'number'),
L(bi('Lendo o movimento','Reading motion'),bi('A inclinação de posição × tempo é velocidade; a de velocidade × tempo é aceleração. A área com sinal sob velocidade × tempo dá deslocamento. Em movimento circular uniforme, a rapidez é constante, mas a direção muda: há aceleração centrípeta.','The slope of position–time is velocity; the slope of velocity–time is acceleration. The signed area under velocity–time gives displacement. In uniform circular motion, speed is constant but direction changes: there is centripetal acceleration.'),'a꜀ = v²/r',bi('Uma volta completa tem deslocamento zero, mas distância igual à circunferência.','A complete turn has zero displacement but a distance equal to the circumference.'),bi('Qual gráfico posição × tempo indica um objeto parado?','Which position–time graph indicates an object at rest?'),[bi('Linha horizontal','Horizontal line'),bi('Reta crescente','Rising straight line'),bi('Curva crescente','Rising curve')],0,bi('Posição constante produz linha horizontal: inclinação e velocidade zero.','Constant position produces a horizontal line: zero slope and velocity.'),'graph'),
L(bi('Saltos e lançamentos','Jumps and projectiles'),bi('Na queda livre ideal, só atua a gravidade: perto da Terra, g ≈ 9,8 m/s² para baixo. No topo de um lançamento vertical, velocidade é zero, mas aceleração não. Sem ar, projéteis têm velocidade horizontal constante e aceleração vertical −g.','In ideal free fall, only gravity acts: near Earth, g ≈ 9.8 m/s² downward. At the top of a vertical throw, velocity is zero but acceleration is not. Without air, projectiles have constant horizontal velocity and vertical acceleration −g.'),'x = v₀ cos(θ)t · y = v₀ sin(θ)t − ½gt²',bi('Uma bola lançada horizontalmente começa a cair imediatamente.','A ball launched horizontally starts falling immediately.'),bi('No ponto mais alto de um lançamento vertical, a aceleração é zero.','At the highest point of a vertical throw, acceleration is zero.'),[bi('Verdadeiro','True'),bi('Falso','False')],1,bi('A gravidade continua atuando. Só a velocidade é zero naquele instante.','Gravity still acts. Only velocity is zero at that instant.'))]},
{name:bi('A força das descobertas','The force of discovery'),topic:bi('Dinâmica','Dynamics'),icon:'🧲',intro:bi('Empurre, puxe e descubra Newton.','Push, pull and discover Newton.'),lessons:[
L(bi('As três leis de Newton','Newton’s three laws'),bi('1ª: sem força resultante, a velocidade se mantém, inclusive zero. 2ª: força resultante produz aceleração. 3ª: ação e reação têm mesmo módulo e sentidos opostos, mas atuam em corpos diferentes; não se cancelam no mesmo corpo.','1st: with zero net force, velocity stays constant, including zero. 2nd: net force produces acceleration. 3rd: action and reaction have equal magnitudes and opposite directions but act on different bodies; they do not cancel on one body.'),'ΣF = ma',bi('Uma força resultante de 6 N em 2 kg produz 3 m/s².','A net 6 N force on 2 kg produces 3 m/s².'),bi('10 N de força resultante em 2 kg produz:','A net force of 10 N on 2 kg produces:'),[bi('5 m/s²','5 m/s²'),bi('20 m/s²','20 m/s²'),bi('0,2 m/s²','0.2 m/s²')],0,bi('a = F/m = 10/2 = 5 m/s².','a = F/m = 10/2 = 5 m/s².')),
L(bi('Quem empurra quem?','Who pushes whom?'),bi('Peso é a força gravitacional. Normal é perpendicular à superfície. Tração é transmitida por cordas esticadas. Atrito se opõe ao deslizamento relativo ou à sua tendência: o estático se ajusta até μₛN; o cinético vale aproximadamente μₖN.','Weight is gravitational force. Normal force is perpendicular to a surface. Tension is transmitted by taut ropes. Friction opposes relative sliding or its tendency: static friction adjusts up to μₛN; kinetic friction is approximately μₖN.'),'P = mg · fₖ = μₖN',bi('Um livro parado numa mesa horizontal, sem outras forças verticais, tem N = mg.','A book at rest on a horizontal table, with no other vertical forces, has N = mg.'),bi('A normal da mesa sobre um livro parado aponta para:','The table’s normal force on a resting book points:'),[bi('Baixo','Down'),bi('Cima','Up'),bi('A direita','Right')],1,bi('A mesa empurra o livro para cima. A reação atua na mesa.','The table pushes the book upward. The reaction acts on the table.')),
L(bi('Molas e rampas','Springs and ramps'),bi('Uma mola ideal exerce força restauradora proporcional à deformação, dentro do limite elástico. Numa rampa de ângulo θ, o peso se decompõe em mg sen θ ao longo da rampa e mg cos θ perpendicular a ela.','An ideal spring exerts a restoring force proportional to deformation, within its elastic limit. On a ramp at angle θ, weight resolves into mg sin θ along the ramp and mg cos θ perpendicular to it.'),'Fₑ = −kx · P∥ = mg sen(θ)',bi('k = 100 N/m e deformação de 0,02 m dão força de módulo 2 N.','k = 100 N/m and deformation of 0.02 m give a force magnitude of 2 N.'),bi('Mola de 200 N/m deformada 0,1 m: qual o módulo da força em N?','A 200 N/m spring deformed 0.1 m: what is force magnitude in N?'),[],20,bi('|F| = 200 × 0,1 = 20 N.','|F| = 200 × 0.1 = 20 N.'),'number'),
L(bi('Curvas e impulsos','Turns and impulses'),bi('Força centrípeta é a resultante para o centro da trajetória circular, não um novo tipo de força. Impulso é força resultante média vezes intervalo de tempo e corresponde à mudança da quantidade de movimento p = mv.','Centripetal force is the net force toward the circle’s center, not a new kind of force. Impulse is average net force times time interval and equals the change in momentum p = mv.'),'F꜀ = mv²/r · J = FₘΔt = Δp',bi('Mover as mãos para trás ao pegar uma bola aumenta o tempo de parada e reduz a força média.','Moving your hands back when catching a ball increases stopping time and reduces average force.'),bi('Uma força constante de 4 N por 3 s gera impulso de:','A constant force of 4 N for 3 s gives an impulse of:'),[bi('12 N·s','12 N·s'),bi('7 N·s','7 N·s'),bi('1,33 N·s','1.33 N·s')],0,bi('J = 4 × 3 = 12 N·s.','J = 4 × 3 = 12 N·s.'))]},
{name:bi('Energia para explorar','Energy to explore'),topic:bi('Trabalho, energia e potência','Work, energy and power'),icon:'⚡',intro:bi('A energia muda de forma. Vamos acompanhar?','Energy changes form. Let’s follow it.'),lessons:[
L(bi('Trabalho de uma força','Work done by a force'),bi('Trabalho é transferência de energia por uma força ao longo de um deslocamento. Para força constante, só conta sua componente paralela ao deslocamento. Força perpendicular não realiza trabalho nesse deslocamento. A unidade é joule (J).','Work is energy transferred by a force through a displacement. For a constant force, only its component parallel to displacement counts. A perpendicular force does no work over that displacement. The unit is joule (J).'),'W = Fd cos(θ)',bi('10 N na direção do deslocamento de 3 m realizam 30 J.','10 N along a 3 m displacement does 30 J of work.'),bi('5 N paralelos a um deslocamento de 4 m realizam quantos J?','5 N parallel to a 4 m displacement does how many J of work?'),[],20,bi('W = 5 × 4 × cos(0°) = 20 J.','W = 5 × 4 × cos(0°) = 20 J.'),'number'),
L(bi('Energia em movimento','Energy in motion'),bi('Energia cinética depende da massa e do quadrado da rapidez. Dobrar a rapidez quadruplica essa energia. Energia potencial gravitacional depende da altura sobre um nível escolhido, quando g é aproximadamente constante.','Kinetic energy depends on mass and the square of speed. Doubling speed quadruples this energy. Gravitational potential energy depends on height above a chosen level, when g is approximately constant.'),'E꜀ = ½mv² · Eₚ = mgh',bi('2 kg a 3 m/s têm energia cinética de 9 J.','2 kg moving at 3 m/s has 9 J of kinetic energy.'),bi('Dobrar a rapidez faz a energia cinética ficar:','Doubling speed makes kinetic energy:'),[bi('Duas vezes maior','Twice as large'),bi('Quatro vezes maior','Four times as large'),bi('Igual','Unchanged')],1,bi('(2v)² = 4v².','(2v)² = 4v².')),
L(bi('A energia se transforma','Energy transforms'),bi('Molas armazenam energia potencial elástica. Energia total de um sistema isolado se conserva. Energia mecânica se conserva se apenas forças conservativas realizam trabalho. Com atrito, parte dela vira energia interna; não desaparece.','Springs store elastic potential energy. Total energy of an isolated system is conserved. Mechanical energy is conserved if only conservative forces do work. With friction, some becomes internal energy; it does not disappear.'),'Eₑ = ½kx² · Eₘ = E꜀ + Eₚ',bi('Numa descida sem atrito, energia potencial diminui e energia cinética aumenta.','On a frictionless descent, potential energy decreases and kinetic energy increases.'),bi('Ao cair sem ar, um objeto transforma:','Falling without air, an object converts:'),[bi('Energia cinética em massa','Kinetic energy into mass'),bi('Energia potencial em cinética','Potential into kinetic energy'),bi('Toda energia em luz','All energy into light')],1,bi('A altura diminui e a rapidez aumenta, conservando energia mecânica nesse modelo.','Height decreases and speed increases, conserving mechanical energy in this model.')),
L(bi('Potência e rendimento','Power and efficiency'),bi('Potência mede a taxa de transferência de energia: joule por segundo é watt (W). Rendimento é energia útil dividida pela recebida. Energia não aproveitada geralmente se dispersa como calor ou som.','Power measures the rate of energy transfer: joule per second is watt (W). Efficiency is useful energy divided by energy input. Unused energy usually disperses as heat or sound.'),'P = E/Δt · η = Eútil/Erecebida',bi('80 J úteis para 100 J recebidos dão rendimento de 80%.','80 useful J from 100 input J gives 80% efficiency.'),bi('600 J transferidos em 3 s correspondem a:','600 J transferred in 3 s corresponds to:'),[bi('200 W','200 W'),bi('1.800 W','1,800 W'),bi('603 W','603 W')],0,bi('P = 600/3 = 200 W.','P = 600/3 = 200 W.'))]},
{name:bi('O segredo do equilíbrio','The secret of balance'),topic:bi('Vetores e estática','Vectors and statics'),icon:'⚖️',intro:bi('Forças, direções e o ponto de equilíbrio.','Forces, directions and the balance point.'),lessons:[
L(bi('Somando setas','Adding arrows'),bi('Vetores no mesmo sentido se somam; em sentidos opostos, seus módulos se subtraem. Para vetores perpendiculares, use Pitágoras. Decompor é escrever componentes em eixos escolhidos.','Vectors in the same direction add; in opposite directions, their magnitudes subtract. For perpendicular vectors, use Pythagoras. Resolving means writing components along chosen axes.'),'Fₓ = F cos(θ) · Fᵧ = F sen(θ)',bi('3 N para leste e 4 N para norte dão resultante de módulo 5 N.','3 N east and 4 N north give a resultant magnitude of 5 N.'),bi('8 N à direita e 3 N à esquerda resultam em:','8 N right and 3 N left produce:'),[bi('11 N à direita','11 N right'),bi('5 N à direita','5 N right'),bi('5 N à esquerda','5 N left')],1,bi('Direita positiva: 8 − 3 = 5 N.','Taking right as positive: 8 − 3 = 5 N.')),
L(bi('Equilíbrio de forças','Force balance'),bi('Equilíbrio translacional é força resultante zero: não há aceleração do centro de massa. Isso permite repouso ou velocidade constante. Para equilíbrio estático de um corpo rígido, forças e torques resultantes devem ser zero.','Translational equilibrium means zero net force: the center of mass does not accelerate. This allows rest or constant velocity. For static equilibrium of a rigid body, net force and net torque must both be zero.'),'ΣF = 0 · Στ = 0',bi('Um quadro pendurado e parado tem forças verticais equilibradas.','A picture hanging at rest has balanced vertical forces.'),bi('Força resultante zero sempre significa velocidade zero.','Zero net force always means zero velocity.'),[bi('Verdadeiro','True'),bi('Falso','False')],1,bi('A velocidade pode ser constante e diferente de zero.','Velocity can be constant and nonzero.')),
L(bi('Centro de massa','Center of mass'),bi('Centro de massa é a posição média ponderada pelas massas, mais próxima da parte pesada. Um objeto apoiado tende a não tombar quando a vertical de seu centro de massa fica dentro da base de apoio.','Center of mass is a mass-weighted average position, closer to the heavier part. A supported object tends not to tip when the vertical through its center of mass stays inside its support base.'),'xCM = (m₁x₁ + m₂x₂)/(m₁ + m₂)',bi('Duas massas iguais nas pontas de uma régua leve têm centro de massa no meio.','Equal masses at the ends of a light ruler have their center of mass in the middle.'),bi('Massas iguais em 0 m e 4 m têm centro de massa em quantos metros?','Equal masses at 0 m and 4 m have their center of mass at how many meters?'),[],2,bi('(0 + 4)/2 = 2 m.','(0 + 4)/2 = 2 m.'),'number'),
L(bi('A força de girar','The power to turn'),bi('Torque, ou momento de uma força, mede a tendência de girar em torno de um eixo. É a força vezes a distância perpendicular do eixo à linha de ação. O sinal depende do sentido de rotação escolhido.','Torque, or moment of a force, measures the tendency to turn about an axis. It is force times the perpendicular distance from the axis to the line of action. Its sign depends on the chosen rotation direction.'),'τ = Fd⊥',bi('Empurrar a porta longe da dobradiça aumenta o braço e facilita girá-la.','Pushing a door far from its hinge increases the lever arm and makes it easier to turn.'),bi('10 N perpendiculares a 0,5 m do eixo geram:','10 N perpendicular at 0.5 m from the axis produces:'),[bi('5 N·m','5 N·m'),bi('20 N·m','20 N·m'),bi('0,05 N·m','0.05 N·m')],0,bi('τ = 10 × 0,5 = 5 N·m.','τ = 10 × 0.5 = 5 N·m.'))]},
{name:bi('Um mergulho na ciência','A dive into science'),topic:bi('Hidrostática','Hydrostatics'),icon:'💧',intro:bi('Por que um navio flutua?','Why does a ship float?'),lessons:[
L(bi('Densidade e pressão','Density and pressure'),bi('Densidade é massa por volume. Pressão é força normal por área: a mesma força numa área menor produz mais pressão. No SI, densidade usa kg/m³ e pressão usa pascal (Pa = N/m²).','Density is mass per volume. Pressure is normal force per area: the same force over a smaller area gives greater pressure. In SI, density uses kg/m³ and pressure uses pascal (Pa = N/m²).'),'ρ = m/V · p = F/A',bi('Raquetes de neve aumentam a área de apoio e reduzem pressão.','Snowshoes increase the support area and reduce pressure.'),bi('Massa 6 kg e volume 0,002 m³ dão densidade de:','Mass 6 kg and volume 0.002 m³ give a density of:'),[bi('3.000 kg/m³','3,000 kg/m³'),bi('0,012 kg/m³','0.012 kg/m³'),bi('12 kg/m³','12 kg/m³')],0,bi('6/0,002 = 3.000 kg/m³.','6/0.002 = 3,000 kg/m³.')),
L(bi('Quanto mais fundo…','The deeper you go…'),bi('A Lei de Stevin descreve pressão num fluido em repouso com densidade constante. Pressão absoluta inclui a pressão na superfície. A pressão manométrica é só o acréscimo ρgh.','Stevin’s law describes pressure in a fluid at rest with constant density. Absolute pressure includes surface pressure. Gauge pressure is only the increase ρgh.'),'p = p₀ + ρgh',bi('Em água a 2 m: acréscimo = 1.000 × 9,8 × 2 = 19.600 Pa.','In water at 2 m: increase = 1,000 × 9.8 × 2 = 19,600 Pa.'),bi('Dobrar a profundidade faz a pressão manométrica:','Doubling depth makes gauge pressure:'),[bi('Dobrar','Double'),bi('Cair pela metade','Halve'),bi('Ficar igual','Stay the same')],0,bi('ρgh é proporcional a h. A pressão absoluta não necessariamente dobra.','ρgh is proportional to h. Absolute pressure does not necessarily double.')),
L(bi('A força dos líquidos','The power of liquids'),bi('Pelo Princípio de Pascal, uma variação de pressão num fluido confinado em equilíbrio se transmite a todos os pontos. Uma prensa ideal multiplica força com área maior, mas o pistão maior se desloca menos: não cria energia.','Pascal’s principle says a pressure change in a confined fluid in equilibrium is transmitted throughout it. An ideal press multiplies force using a larger area, but the larger piston moves less: it does not create energy.'),'F₁/A₁ = F₂/A₂',bi('Área de saída dez vezes maior produz força ideal dez vezes maior.','An output area ten times larger produces ten times the ideal force.'),bi('F₁ = 20 N e A₂ = 3A₁. Qual F₂ em N?','F₁ = 20 N and A₂ = 3A₁. What is F₂ in N?'),[],60,bi('F₂ = 20 × 3 = 60 N.','F₂ = 20 × 3 = 60 N.'),'number'),
L(bi('Afunda ou flutua?','Sink or float?'),bi('Pelo Princípio de Arquimedes, empuxo é o peso do fluido deslocado. Ao flutuar em equilíbrio, empuxo iguala peso. Densidade média menor que a do líquido permite flutuação parcial; maior faz afundar.','Archimedes’ principle says buoyant force is the weight of displaced fluid. In floating equilibrium, buoyancy equals weight. Lower average density than the liquid allows partial flotation; greater density causes sinking.'),'E = ρlíquido g Vsubmerso',bi('Madeira de 600 kg/m³ flutua em água com cerca de 60% do volume submerso.','Wood at 600 kg/m³ floats in water with about 60% of its volume submerged.'),bi('Objeto de 1.200 kg/m³ em água de 1.000 kg/m³ tende a:','An object of 1,200 kg/m³ in water of 1,000 kg/m³ tends to:'),[bi('Flutuar','Float'),bi('Afundar','Sink'),bi('Subir no ar','Rise in air')],1,bi('Mesmo totalmente submerso, empuxo é menor que peso.','Even fully submerged, buoyancy is less than weight.'))]},
{name:bi('Esquenta, esfria, transforma','Warm, cool, transform'),topic:bi('Calorimetria e termometria','Heat and temperature'),icon:'🌡️',intro:bi('Uma viagem pelo mundo das partículas.','A journey into the world of particles.'),lessons:[
L(bi('Temperatura não é calor','Temperature is not heat'),bi('Temperatura está ligada ao estado térmico e movimento microscópico. Calor é energia transferida por diferença de temperatura; espontaneamente vai do quente para o frio. Kelvin é a escala absoluta: 0 K equivale a −273,15 °C.','Temperature relates to thermal state and microscopic motion. Heat is energy transferred due to a temperature difference; spontaneously it flows from hot to cold. Kelvin is the absolute scale: 0 K equals −273.15 °C.'),'T(K) = T(°C) + 273,15 · °F = 1,8 × °C + 32',bi('20 °C = 293,15 K = 68 °F. Não usamos grau antes de K.','20 °C = 293.15 K = 68 °F. There is no degree symbol before K.'),bi('Calor flui espontaneamente:','Heat flows spontaneously:'),[bi('Do quente para o frio','From hot to cold'),bi('Do frio para o quente','From cold to hot'),bi('Do pequeno para o grande, sempre','From small to large, always')],0,bi('A diferença de temperatura determina o sentido espontâneo.','Temperature difference determines the spontaneous direction.')),
L(bi('Quanto calor?','How much heat?'),bi('Calor sensível muda temperatura sem mudar fase: Q = mcΔT. Capacidade térmica C = mc pertence ao corpo; calor específico c caracteriza o material. Calor latente muda fase: Q = mL. Para substância pura a pressão constante, a temperatura fica constante durante a transição.','Sensible heat changes temperature without changing phase: Q = mcΔT. Heat capacity C = mc belongs to the object; specific heat c characterizes the material. Latent heat changes phase: Q = mL. For a pure substance at constant pressure, temperature stays constant during transition.'),'Q = mcΔT · C = mc · Qfase = mL',bi('1 kg de água aquecido em 10 °C exige cerca de 41.800 J, sem perdas.','Heating 1 kg of water by 10 °C requires about 41,800 J with no losses.'),bi('m = 2 kg, c = 500 J/(kg·K), ΔT = 3 K. Qual Q em J?','m = 2 kg, c = 500 J/(kg·K), ΔT = 3 K. What is Q in J?'),[],3000,bi('Q = 2 × 500 × 3 = 3.000 J.','Q = 2 × 500 × 3 = 3,000 J.'),'number'),
L(bi('Três caminhos do calor','Three ways heat travels'),bi('Condução transfere energia por interações microscópicas, sem transporte macroscópico de matéria. Convecção envolve movimento de fluido. Radiação é transferência por ondas eletromagnéticas e ocorre até no vácuo.','Conduction transfers energy through microscopic interactions without bulk matter movement. Convection involves fluid motion. Radiation transfers energy through electromagnetic waves and works even in a vacuum.'),'condução · convecção · radiação',bi('Colher aquece por condução; água circula por convecção; energia solar chega por radiação.','A spoon heats by conduction; water circulates by convection; solar energy arrives by radiation.'),bi('Como a energia do Sol atravessa o vácuo?','How does the Sun’s energy cross a vacuum?'),[bi('Condução','Conduction'),bi('Convecção','Convection'),bi('Radiação','Radiation')],2,bi('Ondas eletromagnéticas não precisam de meio material.','Electromagnetic waves need no material medium.')),
L(bi('Materiais se expandem','Materials expand'),bi('Muitos materiais se expandem ao aquecer. Para pequenas variações de temperatura, a expansão linear é proporcional ao comprimento inicial e à variação de temperatura. Existem exceções, como a água entre 0 e 4 °C.','Many materials expand when heated. For small temperature changes, linear expansion is proportional to initial length and temperature change. Exceptions exist, such as water between 0 and 4 °C.'),'ΔL = αL₀ΔT',bi('Juntas em pontes deixam espaço para dilatação nos dias quentes.','Bridge joints leave room for expansion on hot days.'),bi('Por que pontes precisam de juntas de dilatação?','Why do bridges need expansion joints?'),[bi('Materiais podem crescer ao aquecer','Materials can expand when heated'),bi('Massa dobra no calor','Mass doubles in heat'),bi('Para impedir toda condução','To prevent all conduction')],0,bi('Sem espaço, expansão pode causar tensões e deformações.','Without space, expansion can create stress and deformation.'))]},
{name:bi('A energia por dentro','Energy on the inside'),topic:bi('Termodinâmica','Thermodynamics'),icon:'♨️',intro:bi('Dos motores ao clima do planeta.','From engines to our planet’s climate.'),lessons:[
L(bi('Energia interna','Internal energy'),bi('Energia interna soma energias microscópicas das partículas e interações, não o movimento do corpo inteiro. A lei zero diz que sistemas em equilíbrio térmico com um terceiro estão em equilíbrio térmico entre si: isso fundamenta a temperatura.','Internal energy sums microscopic particle and interaction energies, not the motion of the whole body. The zeroth law says systems in thermal equilibrium with a third are in thermal equilibrium with each other: this underpins temperature.'),'ΔU = Q − W',bi('Um gás pode ganhar energia interna recebendo calor ou sendo comprimido.','A gas can gain internal energy by receiving heat or being compressed.'),bi('Energia interna está ligada a:','Internal energy relates to:'),[bi('Energias microscópicas','Microscopic energies'),bi('Apenas à velocidade do recipiente','Only container speed'),bi('Apenas à altura do recipiente','Only container height')],0,bi('Inclui movimento e interações das partículas do sistema.','It includes motion and interactions of the system’s particles.')),
L(bi('A primeira lei','The first law'),bi('A primeira lei conserva energia. Aqui Q é positivo ao receber calor e W é positivo quando o sistema realiza trabalho no ambiente. Para gás a pressão constante, trabalho de expansão é pΔV.','The first law conserves energy. Here Q is positive for heat received and W is positive for work done by the system on its surroundings. For gas at constant pressure, expansion work is pΔV.'),'ΔU = Q − W · W = pΔV',bi('Receber 100 J e realizar 30 J de trabalho aumenta U em 70 J.','Receiving 100 J and doing 30 J of work increases U by 70 J.'),bi('Recebe 200 J e realiza 80 J de trabalho. Qual ΔU em J?','Receives 200 J and does 80 J of work. What is ΔU in J?'),[],120,bi('200 − 80 = 120 J.','200 − 80 = 120 J.'),'number'),
L(bi('Máquinas térmicas','Heat engines'),bi('Uma máquina cíclica recebe calor de uma fonte quente, realiza trabalho e rejeita calor para uma fonte fria. A segunda lei impede converter todo calor de uma única fonte em trabalho num ciclo. A terceira lei trata do limite da entropia perto do zero absoluto, inalcançável por um número finito de processos.','A cyclic engine receives heat from a hot source, does work and rejects heat to a cold sink. The second law prevents converting all heat from a single source into work in a cycle. The third law concerns entropy near absolute zero, which cannot be reached in a finite number of processes.'),'η = W/Qquente = 1 − Qfrio/Qquente',bi('Receber 500 J e rejeitar 300 J permite 200 J de trabalho e rendimento de 40%.','Receiving 500 J and rejecting 300 J allows 200 J of work and 40% efficiency.'),bi('1.000 J recebidos e 250 J de trabalho dão rendimento de:','1,000 J input and 250 J of work give an efficiency of:'),[bi('25%','25%'),bi('75%','75%'),bi('400%','400%')],0,bi('250/1.000 = 0,25 = 25%.','250/1,000 = 0.25 = 25%.')),
L(bi('O planeta e o calor','Our planet and heat'),bi('O efeito estufa natural mantém a Terra mais quente. Gases como CO₂ absorvem e emitem infravermelho. Aumentar sua concentração altera o balanço energético e intensifica o aquecimento. Isso não é o buraco na camada de ozônio.','The natural greenhouse effect keeps Earth warmer. Gases such as CO₂ absorb and emit infrared radiation. Increasing their concentration changes energy balance and intensifies warming. This is not the ozone hole.'),'energia recebida ↔ energia emitida',bi('Temperatura média estável exige, ao longo do tempo, energia emitida aproximadamente igual à absorvida.','A stable average temperature requires outgoing energy to roughly equal absorbed energy over time.'),bi('Gases de efeito estufa interagem especialmente com:','Greenhouse gases interact especially with:'),[bi('Radiação infravermelha','Infrared radiation'),bi('Força normal das mesas','Normal force from tables'),bi('Apenas a massa dos oceanos','Only ocean mass')],0,bi('Absorver e emitir infravermelho altera a transferência de energia para o espaço.','Absorbing and emitting infrared changes energy transfer to space.'))]},
{name:bi('Além do nosso planeta','Beyond our planet'),topic:bi('Gravitação e astronomia','Gravity and astronomy'),icon:'🪐',intro:bi('Explore órbitas e a história do Universo.','Explore orbits and the Universe’s history.'),lessons:[
L(bi('Massa e peso','Mass and weight'),bi('Massa mede inércia em kg. Peso é força gravitacional em N e muda com o campo gravitacional. A gravitação universal vale para massas pontuais e corpos esféricos com simetria adequada, usando distância entre centros.','Mass measures inertia in kg. Weight is gravitational force in N and changes with gravitational field. Universal gravitation applies to point masses and suitably symmetric spherical bodies, using center-to-center distance.'),'F = GMm/r² · G ≈ 6,6743 × 10⁻¹¹ N·m²/kg²',bi('Na Lua sua massa é igual, mas o peso é cerca de um sexto do terrestre.','On the Moon your mass is unchanged, but weight is about one sixth of its Earth value.'),bi('Dobrar a distância entre massas faz a força ficar:','Doubling distance between masses makes the force:'),[bi('Quatro vezes maior','Four times larger'),bi('Um quarto do valor','One quarter as large'),bi('Metade do valor','Half as large')],1,bi('A dependência é 1/r²: dobrar r divide F por 4.','The dependence is 1/r²: doubling r divides F by 4.')),
L(bi('Vizinhos do Sistema Solar','Solar System neighbors'),bi('O Sol é uma estrela. Os oito planetas em ordem de distância média são Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano e Netuno. A Lua é satélite natural; satélites artificiais são feitos por pessoas.','The Sun is a star. The eight planets in order of average distance are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. The Moon is a natural satellite; artificial satellites are made by people.'),'☀ → ☿ → ♀ → ⊕ → ♂',bi('Vemos a Lua principalmente pela luz solar refletida.','We see the Moon mainly by reflected sunlight.'),bi('Qual é uma estrela?','Which is a star?'),[bi('Lua','Moon'),bi('Terra','Earth'),bi('Sol','Sun')],2,bi('O Sol produz energia por fusão nuclear; Terra é planeta e Lua é satélite.','The Sun produces energy by nuclear fusion; Earth is a planet and the Moon a satellite.')),
L(bi('Órbitas e Kepler','Orbits and Kepler'),bi('Kepler: 1ª, órbitas planetárias são elipses com Sol num foco; 2ª, áreas iguais em tempos iguais; 3ª, T² ∝ a³ para a mesma massa central, sendo a o semieixo maior. Satélite em órbita está em queda livre contínua.','Kepler: 1st, planetary orbits are ellipses with the Sun at one focus; 2nd, equal areas in equal times; 3rd, T² ∝ a³ for the same central mass, where a is semimajor axis. An orbiting satellite is in continuous free fall.'),'vórbita = √(GM/r) · T² ∝ a³',bi('Na órbita circular ideal, gravidade fornece a força centrípeta.','In an ideal circular orbit, gravity supplies centripetal force.'),bi('Em órbita elíptica, o planeta é mais rápido:','In an elliptical orbit, a planet moves faster:'),[bi('Perto do Sol','Near the Sun'),bi('Longe do Sol','Far from the Sun'),bi('Sempre à mesma rapidez','Always at the same speed')],0,bi('Pela lei das áreas, perto do Sol percorre um arco maior no mesmo tempo.','By the area law, near the Sun it covers a longer arc in the same time.')),
L(bi('Universo em expansão','Expanding Universe'),bi('Big Bang descreve a evolução do Universo a partir de um estado quente e denso. Não foi uma explosão em espaço vazio: o próprio espaço se expandiu. Em grandes escalas, galáxias distantes tendem a se afastar; sistemas ligados, como o Sistema Solar, não se expandem assim.','The Big Bang describes the Universe’s evolution from a hot, dense state. It was not an explosion into empty space: space itself expanded. On large scales, distant galaxies tend to recede; bound systems such as the Solar System do not expand this way.'),'v ≈ H₀d',bi('A expansão e a radiação cósmica de fundo apoiam esse modelo.','Expansion and the cosmic microwave background support this model.'),bi('Big Bang descreve:','The Big Bang describes:'),[bi('Uma bomba no Sistema Solar','A bomb in the Solar System'),bi('Evolução de um Universo quente e denso','Evolution of a hot, dense Universe'),bi('Só a formação da Lua','Only the Moon’s formation')],1,bi('É um modelo de evolução cósmica, não uma explosão comum.','It is a model of cosmic evolution, not an ordinary explosion.'))]},
{name:bi('Agora você é cientista','Now you are the scientist'),topic:bi('Investigação científica','Scientific investigation'),icon:'🔬',intro:bi('Pergunte, teste e descubra com evidências.','Ask, test and discover with evidence.'),lessons:[
L(bi('Uma boa pergunta','A good question'),bi('Investigação começa com observação e pergunta estudável. Hipótese é uma explicação ou previsão testável, não certeza. Um experimento pode apoiá-la ou contrariá-la.','Investigation starts with observation and a studyable question. A hypothesis is a testable explanation or prediction, not certainty. An experiment may support or challenge it.'),'observar → perguntar → testar',bi('Hipótese: aumentar a altura da rampa reduz o tempo de descida, mantendo outras condições.','Hypothesis: increasing ramp height reduces descent time, with other conditions held constant.'),bi('Qual hipótese é testável?','Which hypothesis is testable?'),[bi('“Esta rampa é a mais bonita.”','“This ramp is the prettiest.”'),bi('“A altura altera o tempo de descida.”','“Height changes descent time.”'),bi('“O carrinho é impossível de medir.”','“The cart is impossible to measure.”')],1,bi('Podemos variar altura e medir tempo para comparar.','We can vary height and measure time to compare.')),
L(bi('Um teste justo','A fair test'),bi('Mude uma variável de interesse e controle as outras condições. Repita medições. Instrumentos têm resolução e incerteza: nenhuma medida é infinitamente precisa. Registre unidades e condições.','Change one variable of interest and control other conditions. Repeat measurements. Instruments have resolution and uncertainty: no measurement is infinitely precise. Record units and conditions.'),'média = soma / quantidade',bi('Tempos de 2,0 s, 2,2 s e 2,1 s têm média 2,1 s.','Times of 2.0 s, 2.2 s and 2.1 s have a mean of 2.1 s.'),bi('Para testar só a altura da rampa, devemos:','To test only ramp height, we should:'),[bi('Mudar também o carrinho','Also change the cart'),bi('Manter o mesmo carrinho e controlar outras condições','Keep the same cart and control other conditions'),bi('Omitir unidades','Omit units')],1,bi('Controlar condições evita confundir diferentes efeitos.','Controlling conditions avoids confusing different effects.')),
L(bi('Dos dados ao gráfico','From data to graphs'),bi('Faça tabela com unidades. Em geral, a variável modificada fica no eixo horizontal e a medida no vertical. Escolha escalas adequadas e procure padrões sem esconder pontos que contradizem sua ideia.','Make a table with units. Usually the changed variable goes on the horizontal axis and the measured outcome on the vertical. Choose suitable scales and look for patterns without hiding points that contradict your idea.'),'x: independente · y: dependente',bi('Medir posição a cada segundo ajuda a investigar se a rapidez muda.','Measuring position every second helps investigate changes in speed.'),bi('Um dado inesperado deve ser:','An unexpected data point should be:'),[bi('Apagado automaticamente','Automatically deleted'),bi('Trocado pelo desejado','Replaced with the desired value'),bi('Investigado e registrado','Investigated and recorded')],2,bi('Pode ser erro de medição ou algo novo. Investigue e documente.','It may be a measurement error or something new. Investigate and document.')),
L(bi('O que concluir?','What can we conclude?'),bi('Compare dados com a hipótese e reconheça limites. Correlação não prova causa. Conclusões devem ter evidências e podem mudar com novos resultados. Compartilhar métodos permite repetir o teste.','Compare data with the hypothesis and acknowledge limits. Correlation does not prove causation. Conclusions need evidence and may change with new results. Sharing methods allows tests to be repeated.'),'evidências + análise → conclusão',bi('Um resultado numa rampa vale para as condições testadas; outros atritos podem alterá-lo.','A result on one ramp applies to the tested conditions; other friction may change it.'),bi('Quando dados contrariam a hipótese, devemos:','When data contradict a hypothesis, we should:'),[bi('Rever a hipótese e verificar o experimento','Reconsider the hypothesis and check the experiment'),bi('Ignorar dados','Ignore data'),bi('Declarar a hipótese infalível','Declare the hypothesis infallible')],0,bi('A ciência muda explicações quando as evidências exigem.','Science changes explanations when evidence requires it.'))]}
];
